# sigmoid :: (0.0,)
import math

def sigmoid(x):
    if x >= 0:
        return 1.0 / (1.0 + math.exp(-x))
    z = math.exp(x)
    return z / (1.0 + z)

if __name__ == '__main__':
    print(sigmoid((0.0,)))

